use reson_core::{audio::*,models::*};
#[tokio::main]
async fn main(){let out=std::env::temp_dir().join("reson-native-output.wav");let(audio,mut events)=NativeAudio::start(None,Some(out.clone())).unwrap();println!("Devices: {}",audio.devices().unwrap().len());audio.send(AudioCommand::Load{source:StreamSource{url:"/tmp/reson-tone.wav".into(),kind:StreamKind::Progressive,duration_ms:10000},position_ms:0,paused:false}).unwrap();let deadline=tokio::time::sleep(std::time::Duration::from_secs(15));tokio::pin!(deadline);loop{tokio::select!{_= &mut deadline=>{println!("timeout");break;},Some(e)=events.recv()=>{println!("Event {e:?}");if matches!(e,AudioEvent::Ended){break;}}}}audio.send(AudioCommand::Stop).unwrap();audio.send(AudioCommand::Shutdown).unwrap();tokio::time::sleep(std::time::Duration::from_millis(200)).await;println!("Bytes {}",std::fs::metadata(&out).map(|f|f.len()).unwrap_or(0));}
